#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnicodeTableError {
    EmptyFold { index: usize },
    CaseFoldNotIncreasing { index: usize, point: u32, previous: u32 },
    InvertedRange { index: usize, start: u32, end: u32 },
    OverlappingRange { index: usize, start: u32, previous_end: u32 },
}

