impl std::error::Error for UnicodeTableError {}

/// Case-fold rows are strictly increasing and nonempty. Nonprintable ranges
/// are ordered, non-overlapping, and each start is at most its end.
pub fn certify_unicode_tables() -> Result<(usize, usize), UnicodeTableError> {
    let mut previous_point: Option<u32> = None;
    for (index, entry) in CASE_FOLD.iter().enumerate() {
        let (point, fold) = *entry;
        if fold.is_empty() {
            return Err(UnicodeTableError::EmptyFold { index });
        }
        if let Some(previous) = previous_point {
            if point <= previous {
                return Err(UnicodeTableError::CaseFoldNotIncreasing {
                    index,
                    point,
                    previous,
                });
            }
        }
        previous_point = Some(point);
    }
    let mut previous_end: Option<u32> = None;
    for (index, range) in NONPRINTABLE.iter().enumerate() {
        let (start, end) = *range;
        if start > end {
            return Err(UnicodeTableError::InvertedRange { index, start, end });
        }
        if let Some(previous) = previous_end {
            if start <= previous {
                return Err(UnicodeTableError::OverlappingRange {
                    index,
                    start,
                    previous_end: previous,
                });
            }
        }
        previous_end = Some(end);
    }
    Ok((CASE_FOLD.len(), NONPRINTABLE.len()))
}

